    ///
    /// # Examples
    /// ```
    /// # fn main() -> Result<(), sv_lang::Error> {
    /// # let session = sv_lang::Session::new();
    /// # let mut comp = sv_lang::Compilation::new(&session)?;
    /// # comp.add_source("module m(output logic o); initial o = 1; endmodule\n")?;
    /// # let design = comp.compile()?;
